CREATE TRIGGER plm_rt_v1_callback_apply AFTER INSERT ON plm_rt_v1_callback
BEGIN
 UPDATE plm_rt_v1_effect SET state='CONFIRMED',result_id=NEW.result_id,version=version+1,updated_at=NEW.consumed_at WHERE delivery_id=NEW.delivery_id AND kind='UPLOAD' AND state IN ('SENT','UNKNOWN');
 SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'rt_callback_effect_atomicity') END;
 UPDATE plm_rt_v1_job SET state='SUCCEEDED',result_id=NEW.result_id,version=version+1,updated_at=NEW.consumed_at WHERE job_id=NEW.job_id AND state IN ('ACTIVE','UNKNOWN') AND owner_epoch=NEW.owner_epoch AND fencing_token=NEW.fencing_token;
 SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'rt_callback_job_atomicity') END;
END
